#!/usr/bin/env bash
# ZONO — apply "exclusivity-recruitment carousel + Home heat-map" (1 commit).
# Run from anywhere; it cd's into its own repo folder. macOS + Linux safe.
set -euo pipefail
cd "$(dirname "$0")"
echo "→ repo: $(pwd)"
git rev-parse --is-inside-work-tree >/dev/null 2>&1 || { echo "not a git repo"; exit 1; }
echo "→ current HEAD: $(git rev-parse --short HEAD)"
TMP="$(mktemp)"
base64 -d > "$TMP" <<'PATCH_B64'

PATCH_B64
echo "→ applying patch (git am --3way)…"
if git am --3way "$TMP"; then
  rm -f "$TMP"
  echo "✓ applied. New HEAD: $(git rev-parse --short HEAD)"
  echo "→ pushing to origin/main…"
  git push origin main && echo "✓ pushed — Vercel will deploy." || echo "⚠ push failed — run 'git push origin main' manually."
else
  echo "⚠ git am failed; aborting cleanly."
  git am --abort || true
  rm -f "$TMP"
  echo "You can apply manually: git apply --3way '$TMP' (patch kept in scrollback)."
  exit 1
fi
